select @den_ngay as den_ngay, @ngay_ct1 as ngay_ct1, @ngay_ct2 as ngay_ct2
exec zrpt_275_new @den_ngay, @ngay_ct1, @ngay_ct2, @ma_kh, @so_ct, @ma_vt, @kieu_xem, @@unit, '@@sysDatabaseName', @@language, @@userID, @@admin, '1'

			
		
	

	
		
			&OutlineEntry;
			&JavascriptReportFilter; 
			
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid; 
			g._hiddenForms = [];
			g._alterTitle = [null, [['%s1', f.getItem('den_ngay').value, true],['%s2', f.getItem('ngay_ct1').value, true], ['%s3', f.getItem('ngay_ct2').value, true]]];
			//remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}

		
	

